    descriptor = os.open(path, os.O_RDONLY | getattr(os, '\''O_NOFOLLOW'\'', 0) | getattr(os, '\''O_NONBLOCK'\'', 0))
    with os.fdopen(descriptor, '\''rb'\'') as stream:
        before = os.fstat(stream.fileno())
        if not stat.S_ISREG(before.st_mode) or before.st_size > limit:
            raise ValueError('\''unbounded_owned_file'\'')
        data = stream.read(limit + 1)
        after = os.fstat(stream.fileno())
    current = os.lstat(path)
    identity = lambda value: (value.st_dev, value.st_ino, value.st_size, value.st_mtime_ns, value.st_mode)
    if len(data) > limit or identity(before) != identity(after) or identity(after) != identity(current):
        raise ValueError('\''owned_file_changed'\'')
    return data, identity(current)


import hashlib
def write_regular_atomic(path, updated, identity, expected_sha=None):
    if len(updated) > MAXIMUM_FILE_BYTES:
        raise ValueError('\''owned_write_limit'\'')
    temporary = root / ('\''.formal-ai-source-'\'' + secrets.token_hex(12))
    try:
